import numpy as np
from termcolor import colored
import datetime
import sys
import os
from collections import Counter, defaultdict
import json_tricks


def a():
    pass


_srcfile = os.path.normcase(a.__code__.co_filename)


class BaseSink(object):
    @staticmethod
    def _time():
        return datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S,%f')

    def info(self, fmt, *args, **kwargs):
        raise NotImplementedError

    def warning(self, fmt, *args, **kwargs):
        self.info(fmt, *args, **kwargs)

    def verbose(self, fmt, *args, **kwargs):
        pass


class StdoutSink(BaseSink):
    def __init__(self):
        self.freq_count = Counter()

    def info(self, fmt, *args, freq=1, caller=None):
        if args:
            fmt = fmt % args
        self.freq_count[caller] += 1
        if self.freq_count[caller] % freq == 0:
            print("%s - %s - %s" % (colored(self._time(), 'green'),
                                    colored(caller, 'cyan'), fmt), flush=True)

    def warning(self, fmt, *args, **kwargs):
        if args:
            fmt = fmt % args
        self.info(colored(fmt, 'yellow'), **kwargs)


class FileSink(BaseSink):
    def __init__(self, fn):
        self.log_file = open(fn, 'w')
        self.callers = {}

    def info(self, fmt, *args, **kwargs):
        self._kv(level='info', fmt=fmt, args=args, **kwargs)

    def warning(self, fmt, *args, **kwargs):
        self._kv(level='warning', fmt=fmt, args=args, **kwargs)

    def _kv(self, **kwargs):
        kwargs.update(time=datetime.datetime.now())
        self.log_file.write(json_tricks.dumps(kwargs, primitives=True) + '\n')
        self.log_file.flush()

    def verbose(self, fmt, *args, **kwargs):
        self._kv(level='verbose', fmt=fmt, args=args, **kwargs)


class LibLogger(object):
    logfile = ""

    def __init__(self, name='logger', is_root=True):
        self.name = name
        self.is_root = is_root
        self.tab_keys = None
        self.sinks = []
        self.key_prior = defaultdict(np.random.randn)

    def add_sink(self, sink):
        self.sinks.append(sink)

    def info(self, fmt, *args, **kwargs):
        caller = self.find_caller()
        for sink in self.sinks:
            sink.info(fmt, *args, caller=caller, **kwargs)

    def warning(self, fmt, *args, **kwargs):
        caller = self.find_caller()
        for sink in self.sinks:
            sink.warning(fmt, *args, caller=caller, **kwargs)

    def verbose(self, fmt, *args, **kwargs):
        caller = self.find_caller()
        for sink in self.sinks:
            sink.verbose(fmt, *args, caller=caller, **kwargs)

    def find_caller(self):
        """
        Copy from `python.logging` module

        Find the stack frame of the caller so that we can note the source
        file name, line number and function name.
        """
        f = sys._getframe(1)
        if f is not None:
            f = f.f_back
        caller = ''
        while hasattr(f, "f_code"):
            co = f.f_code
            filename = os.path.normcase(co.co_filename)
            if filename == _srcfile:
                f = f.f_back
                continue
            # if stack_info:
            #     sio = io.StringIO()
            #     sio.write('Stack (most recent call last):\n')
            #     traceback.print_stack(f, file=sio)
            #     sio.close()
            # rv = (co.co_filename, f.f_lineno, co.co_name, sinfo)
            rel_path = os.path.relpath(co.co_filename, '')
            caller = f'{rel_path}:{f.f_lineno}'
            break
        return caller


def get_logger(name):
    return LibLogger(name)


logger = get_logger('Logger')
logger.add_sink(StdoutSink())

import numpy as np

class kFoldGenerator():
    '''
    Data Generator
    '''
    k = -1      # the fold number
    x_list = [] # x list with length=k
    y_list = [] # x list with length=k

    # Initializate
    def __init__(self, k, x, y):
        if len(x)!=k or len(y)!=k:
            assert False,'Data generator: Length of x or y is not equal to k.'
        self.k=k
        self.x_list=x
        self.y_list=y

    # Get i-th fold
    def getFold(self, i):
        isFirst=True
        for p in range(self.k): 
            if p!=i:
                if isFirst:
                    train_data       = self.x_list[p]
                    train_targets    = self.y_list[p]
                    isFirst = False
                else:
                    train_data      = np.concatenate((train_data, self.x_list[p]))
                    train_targets   = np.concatenate((train_targets, self.y_list[p]))
            else:
                val_data    = self.x_list[p]
                val_targets = self.y_list[p]
        return train_data,train_targets,val_data,val_targets

    # Get all data x
    def getX(self):
        All_X = self.x_list[0]
        for i in range(1,self.k):
            All_X = np.append(All_X,self.x_list[i], axis=0)
        return All_X

    # Get all label y
    def getY(self):
        All_Y = self.y_list[0]
        for i in range(1,self.k):
            All_Y = np.append(All_Y,self.y_list[i], axis=0)
        return All_Y

    # Get all label y
    def getY_one_hot(self):
        All_Y = self.getY()
        return np.argmax(All_Y, axis=1)

